import json, pandas as pd, numpy as np, re
f=json.load(open('facts.json'))
for fact in f:
    env={'pd':pd,'np':np}
    for k,p in fact['tables'].items(): env[k]=pd.read_csv(p)
    out=str(eval(fact['code'], env))
    nums=re.findall(r'-?\d+(?:\.\d+)?', fact['claim'])
    missing=[]
    for n in nums:
        # look for n with up to 1 decimal among printed numbers
        found=False
        for m in re.findall(r'-?\d+(?:\.\d+)?', out):
            try:
                if abs(float(m)-float(n)) <= 0.05:
                    found=True; break
            except: pass
        if not found: missing.append(n)
    print(fact['id'], 'claim nums:', nums, 'not directly found:', sorted(set(missing)))
EOF

